SELECT
    DATE_FORMAT(sm.monitor_time, '%Y-%m-%d') AS time,
    CAST(SUM(ROUND(sm.power, 2)) AS SIGNED) AS runTime
FROM status_monitor sm


        AND sm.station_id = #{stationId}


        AND UNIX_TIMESTAMP(sm.monitor_time) >= #{startTime}


        AND UNIX_TIMESTAMP(sm.monitor_time) <= #{endTime}

    AND sm.deleted = 0

GROUP BY DATE_FORMAT(sm.monitor_time, '%Y-%m-%d')
ORDER BY time ASC

SELECT COUNT(*) AS totalCount, SUM(CASE WHEN pile_status = 1 THEN 1 ELSE 0 END) AS enableCount, SUM(CASE WHEN fault_flag = 1 THEN 1 ELSE 0 END) AS faultCount, SUM(CASE WHEN pile_status = 3 THEN 1 ELSE 0 END) AS debugCount FROM charging_pile
AND station_id = #{stationId}
AND deleted = 0
